+    .git-log h3 { margin: .7rem 0 .3rem; color: var(--accent-2); font-size: .76rem; letter-spacing: .08em; text-transform: uppercase; }
+    .git-log ul { display: grid; gap: .55rem; margin: 0; padding: 0; list-style: none; }
+    .git-log li { font-size: .77rem; line-height: 1.45; overflow-wrap: anywhere; }
+    .hash { color: var(--accent-ink); font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: .72rem; font-weight: 800; }
+    .belief-list { display: grid; gap: .7rem; }
