+    .opinion-switch { min-height: 44px; padding: .55rem .9rem; border: 1px solid var(--accent-2); border-radius: .65rem; background: var(--surface); color: var(--ink); font-weight: 750; cursor: pointer; }
+    .opinion { margin: .8rem 0 0; }
+    .disagreement-footer { margin: .85rem 0 0; color: var(--muted); font-size: .9rem; }
+    .permission-card { max-width: 690px; overflow: hidden; border: 1px solid #3e3d52; border-radius: 1rem; background: #171722; color: #f4f1de; box-shadow: var(--shadow); }
+    .terminal-title { padding: .8rem 1rem; border-bottom: 1px solid #3e3d52; color: #9fe6db; font: 700 .9rem ui-monospace, SFMono-Regular, Consolas, monospace; }
+    .terminal-body { padding: 1rem; }
+    .terminal-body p { margin-bottom: .9rem; }
+    .terminal-actions { display: flex; flex-wrap: wrap; gap: .65rem; }
+    .terminal-actions button { min-width: 110px; min-height: 44px; padding: .55rem .9rem; border: 1px solid #77758d; border-radius: .55rem; background: #272638; color: #fff; font-weight: 750; cursor: pointer; }
+    .terminal-actions button:first-child { border-color: #7fd7ca; background: #174d49; }
+    .terminal-actions button:hover { filter: brightness(1.18); }
+    .terminal-output { min-height: 3.2em; margin: 1rem 0 0; color: #b9f0c8; font: .88rem/1.55 ui-monospace, SFMono-Regular, Consolas, monospace; white-space: pre-wrap; }
+    .thought-counter { margin: .5rem 0 0; color: #d2cfe0; font-size: .82rem; }
+    .page-footer { width: min(1100px, calc(100% - 2.5rem)); margin: 1rem auto 0; padding: 1.4rem 0 2rem; border-top: 1px solid var(--line); color: var(--muted); text-align: center; font-size: .9rem; }
+    .debug-banner { position: fixed; z-index: 30; top: 1rem; left: 50%; width: max-content; max-width: calc(100% - 2rem); padding: .8rem 1rem; border: 1px solid var(--line); border-radius: .8rem; background: var(--surface); box-shadow: var(--shadow); text-align: center; transform: translateX(-50%); }
+    .confetti-layer { position: fixed; z-index: 29; inset: 0; overflow: hidden; pointer-events: none; }
+    .confetti-piece { position: absolute; top: -2rem; font-size: 1.1rem; animation: fall 2.5s ease-in forwards; }
+    @keyframes fall { to { transform: translateY(110vh) rotate(300deg); opacity: 0; } }
+    [hidden] { display: none !important; }
+    @media (max-width: 900px) {
+      .member-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
