+
+  <main id="main">
+    <header id="top" class="hero">
+      <p class="eyebrow">Agentic Software Engineering · Lab 1</p>
+      <h1><button id="team-name" type="button" aria-label="Team 18">Team 18</button></h1>
+      <p class="hero-joke">Five humans, one agent, zero merge conflicts we will admit to.</p>
+      <p class="hero-subline">Built by an agent. Supervised by humans. Blamed on the agent.</p>
+      <div class="avatar-row" aria-label="The five members of Team 18">
+        <img src="data:image/jpeg;base64," alt="Photo of Annie">
+        <img src="data:image/jpeg;base64," alt="Photo of Avishkar">
