+        });
+      });
+
+      const banner = document.getElementById('debug-banner');
+      const confetti = document.getElementById('confetti-layer');
+      let debugTimer;
+      function showDebugMode() {
+        window.clearTimeout(debugTimer);
+        banner.hidden = false;
+        confetti.replaceChildren();
