+          ? '<strong>Optimists:</strong> No—agents will type most code; humans will review it.'
+          : '<strong>Sceptics:</strong> Mostly yes—people will still hand-write most code, because deciding what to build is the hard part.';
+      });
+
+      let thoughtCount = 0;
+      let outputTimer;
+      const output = document.getElementById('terminal-output');
+      const counter = document.getElementById('thought-counter');
+      const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
+      function typeLine(text, done) {
+        window.clearInterval(outputTimer);
+        output.textContent = '';
+        if (reducedMotion) {
+          output.textContent = text;
+          if (done) done();
+          return;
+        }
+        let index = 0;
+        outputTimer = window.setInterval(() => {
+          output.textContent += text.charAt(index++);
+          if (index >= text.length) {
+            window.clearInterval(outputTimer);
+            if (done) done();
+          }
+        }, 20);
+      }
+      function resetDialog() {
+        window.setTimeout(() => { output.textContent = ''; }, 2200);
+      }
+      document.getElementById('think-button').addEventListener('click', () => {
+        thoughtCount += 1;
+        counter.textContent = `Times a human thought twice: ${thoughtCount}`;
+        typeLine('Wise. Humans: 1, Agent: 0.', resetDialog);
+      });
+      document.getElementById('allow-button').addEventListener('click', () => {
+        const lesson = 'Just kidding, I only wanted to read ../common/. Reading is fine, think twice before writing outside.';
+        typeLine(lesson, () => {
+          output.textContent += '\nLesson learned: reading outside is fine, think twice before writing outside.';
+          resetDialog();
+        });
+      });
+
+      const banner = document.getElementById('debug-banner');
+      const confetti = document.getElementById('confetti-layer');
+      let debugTimer;
+      function showDebugMode() {
+        window.clearTimeout(debugTimer);
+        banner.hidden = false;
+        confetti.replaceChildren();
+        if (!reducedMotion) {
+          const symbols = ['✨', '🎉', '🪲', '🌱'];
+          for (let i = 0; i < 18; i += 1) {
+            const piece = document.createElement('span');
+            piece.className = 'confetti-piece';
+            piece.textContent = symbols[i % symbols.length];
+            piece.style.left = `${(i * 37 + 7) % 100}%`;
+            piece.style.animationDelay = `${(i % 6) * 0.08}s`;
+            confetti.append(piece);
+          }
+        }
+        debugTimer = window.setTimeout(() => {
+          banner.hidden = true;
+          confetti.replaceChildren();
+        }, 4000);
+      }
+      let nameClicks = 0;
+      let nameClickTimer;
+      document.getElementById('team-name').addEventListener('click', () => {
+        nameClicks += 1;
+        window.clearTimeout(nameClickTimer);
+        if (nameClicks >= 5) {
+          nameClicks = 0;
+          showDebugMode();
+        } else {
+          nameClickTimer = window.setTimeout(() => { nameClicks = 0; }, 1200);
+        }
+      });
+      const konami = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'];
+      let keySequence = [];
+      document.addEventListener('keydown', (event) => {
+        keySequence.push(event.key);
+        keySequence = keySequence.slice(-konami.length);
+        if (konami.every((key, index) => keySequence[index] === key)) {
+          keySequence = [];
+          showDebugMode();
+        }
+      });
+    })();
+  </script>
