       <p class="agent-note">Agent: I would explain my diff, but you would have to read it.</p>
     </section>

     <section id="future-of-se" aria-labelledby="future-heading">
       <div class="section-heading">
         <p class="eyebrow">Shared view</p>
         <h2 id="future-heading">Our take on AI and the future of software engineering</h2>
         <p class="section-intro">A few things we think matter, even as the tools change.</p>
         <p class="microcopy">We asked an AI to predict the future. It said “it depends”.</p>
         <p class="agent-note">Agent: I did not break it. I refactored it.</p>
       </div>
       <div class="belief-list" aria-label="Team beliefs">
         <details open>
           <summary>First drafts are cheap; judgement is the bottleneck.</summary>
           <p>Generated code is a starting point. Engineers still need to decide whether it is correct, useful, and reliable.</p>
         </details>
         <details>
           <summary>Prompting is not engineering.</summary>
           <p>Understanding systems, architecture, security, and failure modes is how we use AI well and evaluate what it produces.</p>
         </details>
         <details>
           <summary>Humans stay accountable.</summary>
           <p>“The AI did it” is not an incident report. People remain responsible for the systems they ship.</p>
         </details>
       </div>

       <div class="disagreement">
         <h3>Where we disagree</h3>
         <pre class="stack-trace"><code>Exception: OpinionConflict at optimists.js:10 caused by sceptics.js:42</code></pre>
         <button id="opinion-toggle" class="opinion-switch" type="button" aria-expanded="false" aria-controls="opinion-copy">Show the optimists’ case</button>
         <p id="opinion-copy" class="opinion" hidden><strong>Sceptics:</strong> Mostly yes—people will still hand-write most code, because deciding what to build is the hard part.</p>
         <p class="disagreement-footer">We agree to disagree, then ask the agent to write a test for both opinions. Both pass. Suspicious.</p>
       </div>
     </section>

     <section id="permission" aria-labelledby="permission-heading">
       <div class="section-heading">
         <p class="eyebrow">A small trust exercise</p>
         <h2 id="permission-heading">Permission requested</h2>
         <p class="section-intro">A tiny reminder that tool access deserves a second thought.</p>
       </div>
       <div class="permission-card" aria-label="Fake agent permission request">
         <div class="terminal-title">agent@team18: permission request</div>
         <div class="terminal-body">
           <p>The agent wants to write outside task1_opencode/ (external_directory).</p>
           <div class="terminal-actions">
             <button id="allow-button" type="button">Allow</button>
             <button id="think-button" type="button">Think twice</button>
           </div>
           <p id="terminal-output" class="terminal-output" aria-live="polite"></p>
           <p id="thought-counter" class="thought-counter">Times a human thought twice: 0</p>
         </div>
       </div>
       <p class="agent-note">Agent: Tests pass. I wrote those too.</p>
     </section>
   </main>

   <footer class="page-footer">No bugs were harmed in making this site. Several were promoted to features.</footer>
   <div id="debug-banner" class="debug-banner" role="status" hidden>Debug mode: all 5 humans present, 1 agent supervised, 0 external dependencies.</div>
   <div id="confetti-layer" class="confetti-layer" aria-hidden="true"></div>

   <script>
     (() => {
       const root = document.documentElement;
       const themeButton = document.getElementById('theme-toggle');
       const systemDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
       let theme = systemDark ? 'dark' : 'light';
       try {
         const saved = localStorage.getItem('upb-theme');
         if (saved === 'light' || saved === 'dark') theme = saved;
       } catch (_) { /* Storage can be unavailable in private browsing. */ }

       function applyTheme(nextTheme, persist) {
         theme = nextTheme;
         // data-theme selects the matching light or dark CSS variables.
         root.setAttribute('data-theme', theme);
         const dark = theme === 'dark';
         themeButton.textContent = dark ? 'Back to light, brave human' : 'Night mode (the agent insists)';
         themeButton.setAttribute('aria-label', dark ? 'Switch to light theme' : 'Switch to dark theme');
         if (persist) {
           try { localStorage.setItem('upb-theme', theme); } catch (_) { /* Theme still works for this visit. */ }
         }
       }
       applyTheme(theme, false);
       themeButton.addEventListener('click', () => applyTheme(theme === 'light' ? 'dark' : 'light', true));

       document.querySelectorAll('.card-toggle').forEach((button) => {
         button.addEventListener('click', () => {
           const expanded = button.getAttribute('aria-expanded') === 'true';
           button.setAttribute('aria-expanded', String(!expanded));
           document.getElementById(button.getAttribute('aria-controls')).hidden = expanded;
         });
       });

       const opinionButton = document.getElementById('opinion-toggle');
       const opinion = document.getElementById('opinion-copy');
       opinionButton.addEventListener('click', () => {
         const showOptimists = opinionButton.getAttribute('aria-expanded') !== 'true';
         opinionButton.setAttribute('aria-expanded', String(showOptimists));
         opinion.hidden = !showOptimists;
         opinionButton.textContent = showOptimists ? 'Show the sceptics’ case' : 'Show the optimists’ case';
         opinion.innerHTML = showOptimists
           ? '<strong>Optimists:</strong> No—agents will type most code; humans will review it.'
           : '<strong>Sceptics:</strong> Mostly yes—people will still hand-write most code, because deciding what to build is the hard part.';
       });

       let thoughtCount = 0;
       let outputTimer;
       const output = document.getElementById('terminal-output');
       const counter = document.getElementById('thought-counter');
       const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
       function typeLine(text, done) {
         window.clearInterval(outputTimer);
         output.textContent = '';
         if (reducedMotion) {
           output.textContent = text;
           if (done) done();
           return;
         }
         let index = 0;
         outputTimer = window.setInterval(() => {
           output.textContent += text.charAt(index++);
           if (index >= text.length) {
             window.clearInterval(outputTimer);
             if (done) done();
           }
         }, 20);
       }
       function resetDialog() {
         window.setTimeout(() => { output.textContent = ''; }, 2200);
       }
       document.getElementById('think-button').addEventListener('click', () => {
         thoughtCount += 1;
         counter.textContent = `Times a human thought twice: ${thoughtCount}`;
         typeLine('Wise. Humans: 1, Agent: 0.', resetDialog);
       });
       document.getElementById('allow-button').addEventListener('click', () => {
         const lesson = 'Just kidding, I only wanted to read ../common/. Reading is fine, think twice before writing outside.';
         typeLine(lesson, () => {
           output.textContent += '\nLesson learned: reading outside is fine, think twice before writing outside.';
           resetDialog();
         });
       });

       const banner = document.getElementById('debug-banner');
       const confetti = document.getElementById('confetti-layer');
       let debugTimer;
       function showDebugMode() {
         window.clearTimeout(debugTimer);
         banner.hidden = false;
         confetti.replaceChildren();
         if (!reducedMotion) {
           const symbols = ['✨', '🎉', '🪲', '🌱'];
           for (let i = 0; i < 18; i += 1) {
             const piece = document.createElement('span');
             piece.className = 'confetti-piece';
             piece.textContent = symbols[i % symbols.length];
             piece.style.left = `${(i * 37 + 7) % 100}%`;
             piece.style.animationDelay = `${(i % 6) * 0.08}s`;
             confetti.append(piece);
           }
         }
         debugTimer = window.setTimeout(() => {
           banner.hidden = true;
           confetti.replaceChildren();
         }, 4000);
       }
       let nameClicks = 0;
       let nameClickTimer;
       document.getElementById('team-name').addEventListener('click', () => {
         nameClicks += 1;
         window.clearTimeout(nameClickTimer);
         if (nameClicks >= 5) {
           nameClicks = 0;
           showDebugMode();
         } else {
           nameClickTimer = window.setTimeout(() => { nameClicks = 0; }, 1200);
         }
       });
       const konami = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'];
       let keySequence = [];
       document.addEventListener('keydown', (event) => {
         keySequence.push(event.key);
         keySequence = keySequence.slice(-konami.length);
         if (konami.every((key, index) => keySequence[index] === key)) {
           keySequence = [];
           showDebugMode();
         }
       });
     })();
   </script>
 </body>
 </html>

