Index: lab_1/group-18/task1_opencode/site/index.html
===================================================================
--- lab_1/group-18/task1_opencode/site/index.html	
+++ lab_1/group-18/task1_opencode/site/index.html	
@@ -1,540 +1,540 @@
 <!doctype html>
 <html lang="en">
 <head>
   <meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <meta name="color-scheme" content="light dark">
   <title>Team 18 | Agentic SE Lab</title>
   <style>
     :root {
       color-scheme: light;
       --page: #fff8e7;
       --surface: #fffdf7;
       --surface-soft: #f6efdd;
       --ink: #1d1d1f;
       --muted: #53535a;
       --line: #d8d0bd;
       --accent: #e4007c;
       --accent-ink: #a00056;
       --accent-2: #12645d;
       --focus: #075fbd;
       --shadow: 0 12px 34px rgb(51 42 20 / 7%);
       font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       scroll-behavior: smooth;
     }
     :root[data-theme="dark"] {
       color-scheme: dark;
       --page: #14142b;
       --surface: #1e1e3b;
       --surface-soft: #292947;
       --ink: #f4f1de;
       --muted: #c5c2d4;
       --line: #45445f;
       --accent: #ff62b8;
       --accent-ink: #ff8acb;
       --accent-2: #8de0d5;
       --focus: #9ac7ff;
       --shadow: 0 12px 34px rgb(0 0 0 / 20%);
     }
     @media (prefers-color-scheme: dark) {
       :root:not([data-theme="light"]) {
         color-scheme: dark;
         --page: #14142b; --surface: #1e1e3b; --surface-soft: #292947;
         --ink: #f4f1de; --muted: #c5c2d4; --line: #45445f;
         --accent: #ff62b8; --accent-ink: #ff8acb; --accent-2: #8de0d5;
         --focus: #9ac7ff; --shadow: 0 12px 34px rgb(0 0 0 / 20%);
       }
     }
     * { box-sizing: border-box; }
     html { scroll-padding-top: 5.5rem; }
     body {
       margin: 0;
       background: var(--page);
       color: var(--ink);
       font-size: 1rem;
       line-height: 1.65;
       transition: background-color 180ms ease, color 180ms ease;
     }
     .cursor-glow {
       position: fixed; z-index: 0; inset: 0; pointer-events: none;
       background: radial-gradient(24rem 24rem at var(--spot-x, 50%) var(--spot-y, 18%), color-mix(in srgb, var(--accent) 18%, transparent), transparent 72%);
     }
-    body > *:not(.cursor-glow) { position: relative; z-index: 1; }
+    body > *:not(.cursor-glow):not(.skip-link):not(.site-nav) { position: relative; z-index: 1; }
     a { color: inherit; }
     button { font: inherit; }
     :focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
     .skip-link {
       position: fixed; z-index: 20; top: .75rem; left: .75rem;
       padding: .7rem 1rem; border-radius: .6rem; background: var(--ink); color: var(--page);
       transform: translateY(-180%);
     }
     .skip-link:focus { transform: translateY(0); }
     .site-nav {
       position: sticky; top: 0; z-index: 10;
       display: flex; align-items: center; justify-content: space-between; gap: 1rem;
       min-height: 4.25rem; padding: .6rem max(1.25rem, calc((100vw - 1100px) / 2));
       border-bottom: 1px solid var(--line); background: var(--page);
     }
     .nav-mark { display: inline-flex; min-height: 44px; align-items: center; color: var(--accent-2); font-weight: 800; letter-spacing: .04em; text-decoration: none; }
     .nav-links { display: flex; align-items: center; gap: 1.25rem; }
     .nav-links a { display: inline-flex; min-height: 44px; align-items: center; color: var(--muted); font-size: .94rem; text-decoration-thickness: .08em; text-underline-offset: .2em; }
     .nav-links a:hover { color: var(--ink); }
     .theme-toggle, .action-button {
       min-height: 44px; padding: .55rem .85rem; border: 1px solid var(--line); border-radius: 999px;
       background: var(--surface); color: var(--ink); cursor: pointer;
     }
